{"path": "/home/bob/books/No_Blue_Sky_Series/pipeline_all_books.py", "content": "#!/usr/bin/env python3
"""
Unified Publishing Pipeline for No Blue Sky Books 2-5.

Processes each book sequentially:
  1. Read & analyze (md or HTML)
  2. Build print-ready HTML with table-based TOC and hardcoded page numbers
  3. Generate final PDF (6"x9" with bleeds)
  4. Generate EPUB 3

Usage:
  python3 pipeline_all_books.py
"""

import os, re, sys, subprocess, tempfile, io, zipfile
from datetime import datetime, timezone
from xml.sax.saxutils import escape as xmlescape


# ══════════════════════════════════════════════════════════════════════════
# Book Configuration
# ══════════════════════════════════════════════════════════════════════════

BOOKS = [
    {
        "num": 2,
        "title": "No Blue Sky: The Oxygen Gamble",
        "subtitle": "A novel of Mars, sovereignty, and the birth of a civilization",
        "series": "No Blue Sky Series • Book II",
        "slug_title": "The_Oxygen_Gamble",
        "dir": "/home/bob/books/No_Blue_Sky_Series/Book_II_The_Oxygen_Gamble",
        "manuscript": "manuscript.md",
        "input_type": "md",
        "author": "Bob Mills",
        "description": "A novel of Mars, sovereignty, and the birth of a civilization. Salvage, diplomacy, and the forging of Martian identity through the generations."
    },
    {
        "num": 3,
        "title": "No Blue Sky: Rivers Under Mars",
        "subtitle": "The Third Generation",
        "series": "No Blue Sky Series • Book III",
        "slug_title": "Rivers_Under_Mars",
        "dir": "/home/bob/books/No_Blue_Sky_Series/Book_III_Rivers_Under_Mars",
        "manuscript": None,
        "input_type": "html",
        "author": "Bob Mills",
        "description": "A novel of first contact, alien signals, and humanity's future among the stars. The third generation confronts what lies beyond."
    },
    {
        "num": 4,
        "title": "No Blue Sky: The Red Charter",
        "subtitle": "Book IV of the No Blue Sky Series",
        "series": "No Blue Sky Series • Book IV",
        "slug_title": "The_Red_Charter",
        "dir": "/home/bob/books/No_Blue_Sky_Series/Book_IV_The_Red_Charter",
        "manuscript": None,
        "input_type": "html",
        "author": "Bob Mills",
        "description": "A novel of the first permanent Moon base. From the Artemis Accord to the foundation of lunar civilization."
    },
    {
        "num": 5,
        "title": "No Blue Sky: The First Martian Nation",
        "subtitle": "Book V of the No Blue Sky Series",
        "series": "No Blue Sky Series • Book V",
        "slug_title": "The_First_Martian_Nation",
        "dir": "/home/bob/books/No_Blue_Sky_Series/Book_V_The_First_Martian_Nation",
        "manuscript": None,
        "input_type": "html",
        "author": "Bob Mills",
        "description": "A novel of lunar survival, discovery, and the birth of a permanent settlement. From first light to the declaration of a new home."
    },
]

PUBLISHER = "Self-Published"
LANG = "en"
COVER_JPG = None  # No cover images for books 2-5; EPUB will work without


# ══════════════════════════════════════════════════════════════════════════
# Helpers
# ══════════════════════════════════════════════════════════════════════════

def slug(name):
    """Filesystem-safe slug from a heading string."""
    s = name.lower().replace(" ", "-").replace(":", "").replace("—", "-").replace("--", "-")
    s = re.sub(r"[^a-z0-9.-]", "", s)[:60]
    return s


def count_words(text):
    """Count words in a text string."""
    return len(text.split())


def md_to_html_body(body_lines, indent=0):
    """Convert parsed body lines to HTML paragraphs."""
    html_parts = []
    for line in body_lines:
        stripped = line.strip()
        if not stripped:
            continue

        # Horizontal rule
        if re.match(r"^---+\s*$", stripped) and len(stripped) <= 5:
            html_parts.append("<hr/>")
            continue

        # Epigraph / italic section lines (single * on each side, not bold)
        if re.match(r"^\*[^*]+\*$", stripped) and "**" not in stripped:
            inner = stripped.strip("*").strip()
            html_parts.append(f'<p class="epigraph">{xmlescape(inner)}</p>')
            continue

        # Italic lines with content (scene breaks)
        if stripped.startswith("*") and stripped.endswith("*") and "**" not in stripped:
            inner = stripped.strip("*").strip()
            html_parts.append(f'<p class="scene-break">{xmlescape(inner)}</p>')
            continue

        # Blockquotes
        if stripped.startswith(">"):
            quote = stripped[1:].strip()
            html_parts.append(f"<blockquote><p>{xmlescape(quote)}</p></blockquote>")
            continue

        # Regular paragraph - handle inline formatting
        text = stripped
        text = re.sub(r"\*\*([^*]+)\*\*", r"<strong>\1</strong>", text)
        text = re.sub(r"(?<!\*)\*([^*]+)\*(?!\*)", r"<em>\1</em>", text)

        html_parts.append(f"<p>{text}</p>")

    return "\n".join(html_parts)


