# PARSING: Manuscript Markdown (for Book 2)
# ══════════════════════════════════════════════════════════════════════════

def parse_manuscript(text):
    """Parse manuscript.md into structured entries."""
    lines = text.split("\n")
    entries = []

    # Front matter: everything before the first ## Chapter
    i = 0
    front_lines = []
    while i < len(lines):
        stripped = lines[i].strip()
        if re.match(r"^## Chapter \d", stripped):
            break
        front_lines.append(lines[i])
        i += 1
    entries.append({
        "type": "front",
        "heading": "Front Matter",
        "level": "h1",
        "body": front_lines,
        "slug": "front-matter"
    })

    chapter_pattern = re.compile(r"^## (Chapter \d+[—–-]?.+)$")
    current_entry = None
    current_body = []

    for idx in range(i, len(lines)):
        stripped = lines[idx].strip()
        m = chapter_pattern.match(stripped)
        if m:
            if current_entry is not None:
                current_entry["body"] = current_body
                entries.append(current_entry)
            current_entry = {
                "type": "chapter",
                "heading": m.group(1),
                "level": "h2",
                "body": [],
                "slug": slug(m.group(1))
            }
            current_body = []
            continue

        if current_entry is not None:
            current_body.append(lines[idx])

    if current_entry is not None:
        current_entry["body"] = current_body
        entries.append(current_entry)

    return entries


