# PARSING: Existing HTML (for Books 3-5)
# ══════════════════════════════════════════════════════════════════════════

def parse_html_source(html_text, book_title):
    """Parse existing HTML document into structured entries.

    Extract chapter titles from <h1> tags and body content from <p> tags.
    """
    entries = []

    # Front matter entry (we'll build title/copyright from metadata)
    entries.append({
        "type": "front",
        "heading": "Front Matter",
        "level": "h1",
        "body": [],
        "slug": "front-matter"
    })

    # Find all chapter divs or groups
    # Pattern: <h1>Chapter N — Title</h1> followed by <p>...</p> content
    # Split by <h1> tags
    chapter_pattern = re.compile(r'<h1>(.*?)</h1>\s*(.*?)(?=<h1>|\Z)', re.DOTALL)

    # Find all h1 content
    for m in chapter_pattern.finditer(html_text):
        heading_text = m.group(1).strip()
        body_html = m.group(2).strip()

        # Skip title page h1 (the book title itself)
        if heading_text == book_title or "No Blue Sky" in heading_text and "Chapter" not in heading_text:
            continue

        # Skip TOC page h1
        if heading_text == "Table of Contents":
            continue

        # Skip about-author h1
        if heading_text == "About the Author":
            continue

        # Extract paragraphs from body_html
        p_pattern = re.compile(r'<p[^>]*>(.*?)</p>', re.DOTALL)
        paragraphs = p_pattern.findall(body_html)

        body_lines = []
        for p in paragraphs:
            # Clean up HTML entities and tags
            p_text = p.strip()
            if not p_text:
                continue
            # Convert <em> back to markdown * for consistency
            p_text = re.sub(r'<em>(.*?)</em>', r'*\1*', p_text)
            p_text = re.sub(r'<strong>(.*?)</strong>', r'**\1**', p_text)
            p_text = re.sub(r'<br\s*/?>', '\n', p_text)
            body_lines.append(p_text)

        chapter_type = "chapter"

        entries.append({
            "type": chapter_type,
            "heading": heading_text,
            "level": "h1",
            "body": body_lines,
            "slug": slug(heading_text)
        })

    return entries


# ══════════════════════════════════════════════════════════════════════════
# HTML Building
# ══════════════════════════════════════════════════════════════════════════

def build_toc_html(entries, page_numbers=None, book_title="", book_subtitle=""):
    """Build TOC as an HTML table with chapter titles and page numbers."""
    toc_rows = []
    for entry in entries:
        if entry["type"] == "front":
            continue

        pnum = ""
        if page_numbers and entry["slug"] in page_numbers and entry["type"] in ("chapter", "interstitial"):
            pnum = str(page_numbers[entry["slug"]])
        elif not page_numbers and entry["type"] in ("chapter", "interstitial"):
            pnum = "•••"

        row_class = f'toc-{entry["type"]}'

        if entry["type"] == "part":
            toc_rows.append(
                f'<tr class="{row_class}">'
                f'<td colspan="2">{xmlescape(entry["heading"])}</td>'
                f'</tr>'
            )
        elif entry["type"] == "interstitial":
            toc_rows.append(
                f'<tr class="{row_class}">'
                f'<td class="toc-chapter">{xmlescape(entry["heading"])}</td>'
                f'<td class="toc-page-num">{pnum}</td>'
                f'</tr>'
            )
        elif entry["type"] == "chapter":
            toc_rows.append(
                f'<tr>'
                f'<td class="toc-chapter">{xmlescape(entry["heading"])}</td>'
                f'<td class="toc-page-num">{pnum}</td>'
                f'</tr>'
            )

    return f"""
<div class="toc-page">
  <h1>Contents</h1>
  <table class="toc-table">
  {chr(10).join(toc_rows)}
  </table>
</div>
"""


