# Page Number Extraction from PDF
# ══════════════════════════════════════════════════════════════════════════

def extract_page_numbers_from_pdf(pdf_path, entries):
    """Extract actual page numbers for each chapter from PDF."""
    if not os.path.exists(pdf_path):
        print(f"  WARNING: PDF not found at {pdf_path}")
        return {}

    # Get page count
    result = subprocess.run(
        ["pdfinfo", pdf_path],
        capture_output=True, text=True
    )
    page_count = 0
    for line in result.stdout.split("\n"):
        if "Pages" in line:
            page_count = int(line.split(":")[1].strip())
            break

    if page_count == 0:
        print("  WARNING: Could not determine PDF page count")
        return {}

    print(f"  PDF has {page_count} pages. Extracting chapter locations...")

    chapter_entries = [e for e in entries if e["type"] in ("chapter", "interstitial")]

    # Extract full text of each page
    page_texts = {}
    for pg in range(1, page_count + 1):
        result = subprocess.run(
            ["pdftotext", "-f", str(pg), "-l", str(pg), pdf_path, "-"],
            capture_output=True, text=True
        )
        page_texts[pg] = result.stdout

    # Find where content starts (after TOC)
    content_start_page = 3  # Assume at least title, copyright, TOC pages

    # Find actual start by scanning for first chapter heading that's not in TOC
    for pg in range(1, page_count + 1):
        text = page_texts[pg]
        heading_count = sum(1 for e in chapter_entries if e["heading"] in text)
        if heading_count >= 1 and pg > 3:
            content_start_page = pg - 1
            break

    # Build signatures for each chapter
    page_numbers = {}
    chapter_signatures = {}
    for entry in chapter_entries:
        body_lines = entry["body"]
        sig = None
        for line in body_lines:
            stripped = line.strip()
            if not stripped:
                continue
            if re.match(r"^\*[^*]+\*$", stripped) and "**" not in stripped:
                continue
            if stripped.startswith(">"):
                stripped = stripped[1:].strip()
            # Get first 60 chars
            sig = stripped[:60]
            break
        if sig:
            chapter_signatures[entry["slug"]] = sig

    for entry in chapter_entries:
        sig = chapter_signatures.get(entry["slug"])
        if not sig:
            page_numbers[entry["slug"]] = 0
            continue

        found_page = None
        for pg in range(content_start_page, page_count + 1):
            text = page_texts.get(pg, "")
            if sig in text:
                found_page = pg
                break

        if found_page is None:
            # Fallback: search for heading text on pages after TOC
            for pg in range(content_start_page, page_count + 1):
                text = page_texts.get(pg, "")
                if entry["heading"] in text:
                    found_page = pg
                    break

        if found_page:
            page_numbers[entry["slug"]] = found_page
            print(f"    {entry['heading']} -> page {found_page}")
        else:
            print(f"    WARNING: Could not find '{entry['heading']}' in PDF")
            page_numbers[entry["slug"]] = 0

    return page_numbers


# ══════════════════════════════════════════════════════════════════════════
# PDF Generation
# ══════════════════════════════════════════════════════════════════════════

def generate_pdf(html_path, pdf_path):
    """Generate PDF from HTML using WeasyPrint."""
    import weasyprint
    print(f"  Generating PDF: {pdf_path}")
    weasyprint.HTML(filename=html_path).write_pdf(pdf_path)
    size = os.path.getsize(pdf_path)
    result = subprocess.run(
        ["pdfinfo", pdf_path],
        capture_output=True, text=True
    )
    pages = 0
    for line in result.stdout.split("\n"):
        if "Pages" in line:
            pages = int(line.split(":")[1].strip())
            break
    print(f"  PDF generated: {pdf_path} ({size:,} bytes, {pages} pages)")
    return pages


def write_html(html_text, path):
    """Write HTML to file."""
    with open(path, "w", encoding="utf-8") as f:
        f.write(html_text)
    print(f"  HTML written: {path} ({len(html_text):,} bytes)")


