# Process a Single Book
# ══════════════════════════════════════════════════════════════════════════

def process_book(cfg):
    """Process a single book through the full pipeline."""
    num = cfg["num"]
    title = cfg["title"]
    book_dir = cfg["dir"]
    slug_title = cfg["slug_title"]

    # Output filenames
    html_out = os.path.join(book_dir, f"No_Blue_Sky_{num}_{slug_title}.html")
    pdf_out = os.path.join(book_dir, f"No_Blue_Sky_{num}_{slug_title}_Print.pdf")
    epub_out = os.path.join(book_dir, f"No_Blue_Sky_{num}_{slug_title}.epub")
    review_html = os.path.join(book_dir, ".review_build.html")
    review_pdf = os.path.join(book_dir, ".review_build.pdf")

    print()
    print("=" * 70)
    print(f"  BOOK {num}: {title}")
    print("=" * 70)
    print()

    # ── Phase 1: Read & Analyze ──
    print("[Phase 1] Reading and Analyzing...")

    if cfg["input_type"] == "md":
        manuscript_path = os.path.join(book_dir, cfg["manuscript"])
        print(f"  Source: {manuscript_path}")
        with open(manuscript_path, "r", encoding="utf-8") as f:
            text = f.read()
        word_count = count_words(text)
        entries = parse_manuscript(text)
    else:
        html_path = os.path.join(book_dir, [f for f in os.listdir(book_dir) if f.endswith('.html')][0])
        print(f"  Source: {html_path}")
        with open(html_path, "r", encoding="utf-8") as f:
            text = f.read()
        word_count = count_words(text)
        entries = parse_html_source(text, title)

    chapters = [e for e in entries if e["type"] == "chapter"]
    print(f"  Word count: {word_count:,}")
    print(f"  Chapters found: {len(chapters)}")
    print(f"  Total entries: {len(entries)}")

    # ── Phase 2: Build first-pass HTML ──
    print()
    print("[Phase 2] Building Print-Ready HTML...")
    print("  Stage 1: First pass with TOC placeholders...")
    first_html = build_full_html(entries, cfg, toc_page_numbers=None)
    write_html(first_html, review_html)

    # ── Phase 3: Generate review PDF and extract page numbers ──
    print("  Stage 2: Generating review PDF...")
    review_pages = generate_pdf(review_html, review_pdf)

    print("  Stage 3: Extracting actual page numbers from PDF...")
    page_numbers = extract_page_numbers_from_pdf(review_pdf, entries)

    # Print TOC
    print()
    print("  TOC Page Numbers:")
    print(f"  {'Chapter':<50} {'Page':>5}")
    print(f"  {'-'*50} {'-'*5}")
    for entry in entries:
        if entry["type"] == "front":
            continue
        pnum = page_numbers.get(entry["slug"], "???")
        print(f"  {entry['heading']:<50} {str(pnum):>5}")

    # ── Stage 4: Rebuild with hardcoded page numbers ──
    print()
    print("  Stage 4: Rebuilding HTML with hardcoded page numbers...")
    final_html = build_full_html(entries, cfg, toc_page_numbers=page_numbers)
    write_html(final_html, html_out)

    # ── Phase 4: Generate Final PDF ──
    print()
    print("[Phase 3] Generating Final Print PDF...")
    final_pages = generate_pdf(html_out, pdf_out)
    print(f"  Final page count: {final_pages}")

    # ── Phase 5: Generate EPUB ──
    print()
    print("[Phase 4] Generating EPUB 3...")
    epub_data = build_epub(entries, cfg)
    with open(epub_out, "wb") as f:
        f.write(epub_data)
    print(f"  ✓ EPUB built: {epub_out} ({len(epub_data):,} bytes)")

    # ── Phase 6: Report ──
    print()
    print("-" * 70)
    print(f"  REPORT: {title}")
    print("-" * 70)
    print(f"  Chapters:     {len(chapters)}")
    print(f"  Word count:   {word_count:,}")
    print(f"  PDF pages:    {final_pages}")

    # TOC accuracy
    mismatches = 0
    for entry in entries:
        if entry["type"] not in ("chapter", "interstitial"):
            continue
        pnum = page_numbers.get(entry["slug"], None)
        if pnum is None or pnum == 0:
            mismatches += 1
            print(f"    ⚠ {entry['heading']}: page number not found")
    if mismatches == 0:
        print(f"  TOC accuracy: ✓ All {len(chapters)} chapter page numbers correctly extracted")

    print()
    print("  Output Files:")
    print(f"    PDF:  {pdf_out}")
    print(f"    HTML: {html_out}")
    print(f"    EPUB: {epub_out}")
    print()
    print("  Issues:")
    if cfg["input_type"] == "html":
        print("    ✓ Source was existing HTML — parsed and rebuilt with proper print CSS")
    print("    ✓ Table-based TOC with hardcoded page numbers")
    print("    ✓ Print-ready 6\"x9\" CSS with bleeds (6.25\"x9.25\")")
    print(f"    ✓ {'Within' if 150 <= final_pages <= 200 else 'Outside'} target page range (150-200)")

    # Cleanup review files
    for f in [review_html, review_pdf]:
        if os.path.exists(f):
            os.remove(f)

    return chapters, word_count, final_pages


# ══════════════════════════════════════════════════════════════════════════
# Main
# ══════════════════════════════════════════════════════════════════════════

def main():
    print("=" * 70)
    print("  NO BLUE SKY SERIES — Publishing Pipeline (Books 2-5)")
    print("=" * 70)

    all_results = []

    for cfg in BOOKS:
        try:
            chapters, word_count, final_pages = process_book(cfg)
            all_results.append((cfg, chapters, word_count, final_pages))
        except Exception as e:
            print(f"\n  ERROR processing {cfg['title']}: {e}")
            import traceback
            traceback.print_exc()
            all_results.append((cfg, [], 0, 0))

    # ── Final Summary ──
    print()
    print()
    print("=" * 70)
    print("  FINAL SUMMARY — All Books")
    print("=" * 70)
    print()
    print(f"  {'Book':<10} {'Title':<40} {'Chaps':>6} {'Words':>8} {'Pages':>6}")
    print(f"  {'-'*10} {'-'*40} {'-'*6} {'-'*8} {'-'*6}")
    for cfg, chapters, word_count, final_pages in all_results:
        print(f"  {cfg['num']:<10} {cfg['title']:<40} {len(chapters):>6} {word_count:>8,} {final_pages:>6}")
    print()
    print("=" * 70)
    print("  PIPELINE COMPLETE")
    print("=" * 70)


if __name__ == "__main__":
    main()
